'use client';

import { useState } from 'react';
import axios from 'axios';
import styles from './Form.module.scss'; // Opcional, o CSS Modules

export default function ZoneForm() {
  const [formData, setFormData] = useState({ zoneName: '', interfaces: '' });
  const [generatedScript, setGeneratedScript] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Transforma a string "wan1, wan2" num array ["wan1", "wan2"]
    const interfacesArray = formData.interfaces.split(',').map(i => i.trim());

    try {
      const response = await axios.post('http://localhost:3001/api/generate', {
        type: 'zone',
        payload: {
          zoneName: formData.zoneName,
          interfaces: interfacesArray
        }
      });
      setGeneratedScript(response.data.script);
    } catch (error) {
      console.error('Erro ao gerar script', error);
    }
  };

  return (
    <div className="card p-4 shadow-sm mb-4">
      <h4 className="mb-3">Criar Zona de Interfaces</h4>
      <form onSubmit={handleSubmit}>
        <div className="row mb-3">
          <div className="col-md-6">
            <label className="form-label">Nome da Zona (ex: ZN_INTERNET)</label>
            <input type="text" className="form-control" required
              onChange={e => setFormData({...formData, zoneName: e.target.value})} />
          </div>
          <div className="col-md-6">
            <label className="form-label">Interfaces (separadas por vírgula)</label>
            <input type="text" className="form-control" placeholder="ex: wan1, wan2" required
              onChange={e => setFormData({...formData, interfaces: e.target.value})} />
          </div>
        </div>
        <button type="submit" className="btn btn-primary">Gerar Script de Zona</button>
      </form>

      {/* Caixa de resultado do Script */}
      {generatedScript && (
        <div className="mt-4">
          <h5>Cole no terminal do FortiGate:</h5>
          <pre className="bg-dark text-success p-3 rounded">
            <code>{generatedScript}</code>
          </pre>
          <button 
            className="btn btn-outline-secondary btn-sm" 
            onClick={() => navigator.clipboard.writeText(generatedScript)}
          >
            Copiar Script
          </button>
        </div>
      )}
    </div>
  );
}